function moves(s,p){
  const out=[];if(!p)return out;
  const radius=p.kind==='king'||p.kind==='guard'||p.kind==='pawn'?1:p.kind==='horse'||p.kind==='elephant'?2:null;
  const x0=radius===null?0:Math.max(0,Math.ceil(p.x-radius)),x1=radius===null?8:Math.min(8,Math.floor(p.x+radius));
  const y0=radius===null?0:Math.max(0,Math.ceil(p.y-radius)),y1=radius===null?9:Math.min(9,Math.floor(p.y+radius));
  for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){
    if((p.kind==='rook'||p.kind==='cannon')&&x!==p.x&&y!==p.y)continue;
    if(canMove(s,p,x,y))out.push({x,y,capture:!!at(s,x,y)});
  }
  if(p.kind==='king'){
    for(const q of s.pieces)if(q.kind==='king'&&q.side!==p.side&&q.x===p.x&&!out.some(m=>m.x===q.x&&m.y===q.y)&&canMove(s,p,q.x,q.y))out.push({x:q.x,y:q.y,capture:true});
    out.sort((a,b)=>a.y-b.y||a.x-b.x);
  }
  return out;
}
